bulk_write_result(5000, 5000).

clause(1, bulk_write_chars(anonymous(1), 0), !).
clause(2,
       bulk_write_chars(var('Stream'), var('N')),
       (var('N') > 0,
        var('Code') is 97 + var('N') mod 26,
        char_code(var('Char'), var('Code')),
        put_char(var('Stream'), var('Char')),
        var('N1') is var('N') - 1,
        bulk_write_chars(var('Stream'), var('N1')))).
clause(3,
       count_chars(var('Stream'), var('Acc'), var('Count')),
       (get_char(var('Stream'), var('Char')),
        count_chars_step(var('Char'), var('Stream'), var('Acc'), var('Count')))).
clause(4, count_chars_step(end_of_file, anonymous(1), var('Count'), var('Count')), !).
clause(5,
       count_chars_step(anonymous(1), var('Stream'), var('Acc'), var('Count')),
       (var('Acc1') is var('Acc') + 1, count_chars(var('Stream'), var('Acc1'), var('Count')))).
clause(6, bulk_write_path('/tmp/eyeprolog-bulk-stream-write-example.txt'), true).
clause(7,
       bulk_write_result(var('Requested'), var('Counted')),
       (var('Requested') = 5000,
        bulk_write_path(var('Path')),
        open(var('Path'), write, var('Out'), [type(text)]),
        bulk_write_chars(var('Out'), var('Requested')),
        close(var('Out')),
        open(var('Path'), read, var('In'), [type(text)]),
        count_chars(var('In'), 0, var('Counted')),
        close(var('In')))).

